#!/usr/bin/env python3
"""
dom_bridge_client.py
====================
Drop this file anywhere Claude Code can find it.
Import it to scrape live DOM from your authenticated Chrome tabs.

Quick usage:
    import dom_bridge_client as dbc

    # Get full page (text + html) from active tab
    result = dbc.scrape()

    # Get visible text only
    text = dbc.text()

    # Get text from a specific site you have open
    text = dbc.text(url_filter='twitter.com')

    # Query specific elements
    items = dbc.select('.post-content')

    # Get full HTML
    html = dbc.html()

    # Run arbitrary JS in the page
    val = dbc.evaluate('document.querySelectorAll("a").length')
"""

import json
import uuid
import socket
import threading
import time

try:
    import websocket  # websocket-client
    HAS_WS = True
except ImportError:
    HAS_WS = False

PORT = 9229
DEFAULT_TIMEOUT = 10


def _send_request(msg, timeout=DEFAULT_TIMEOUT):
    """Low-level: send a request over WebSocket and wait for response."""
    if not HAS_WS:
        raise ImportError(
            "websocket-client not installed. Run: pip install websocket-client"
        )

    result_container = {}
    event = threading.Event()
    request_id = msg['request_id']

    ws = websocket.WebSocketApp(
        f'ws://localhost:{PORT}',
        on_message=lambda ws, data: _on_message(ws, data, request_id, result_container, event),
        on_error=lambda ws, err: result_container.update({'error': str(err)}),
        on_open=lambda ws: ws.send(json.dumps(msg))
    )

    t = threading.Thread(target=ws.run_forever, daemon=True)
    t.start()

    got_result = event.wait(timeout=timeout)
    ws.close()

    if not got_result:
        return {'success': False, 'error': f'Timeout after {timeout}s. Is the server running?'}
    return result_container.get('result', {'success': False, 'error': 'No response'})


def _on_message(ws, data, request_id, container, event):
    try:
        parsed = json.loads(data)
        if parsed.get('request_id') == request_id:
            container['result'] = parsed
            event.set()
            ws.close()
    except Exception:
        pass


def _build_msg(action, **kwargs):
    msg = {
        'type': 'SCRAPE_REQUEST',
        'request_id': str(uuid.uuid4()),
        'action': action,
    }
    msg.update(kwargs)
    return msg


def scrape(url_filter=None, timeout=DEFAULT_TIMEOUT):
    """Return dict with url, title, text, and html of active tab."""
    return _send_request(_build_msg('default', url_filter=url_filter), timeout)


def text(url_filter=None, timeout=DEFAULT_TIMEOUT):
    """Return visible text content of active tab as a string."""
    result = _send_request(_build_msg('text_content', url_filter=url_filter), timeout)
    if result.get('success'):
        return result['data']
    raise RuntimeError(result.get('error', 'Unknown error'))


def html(url_filter=None, timeout=DEFAULT_TIMEOUT):
    """Return full HTML of active tab as a string."""
    result = _send_request(_build_msg('full_html', url_filter=url_filter), timeout)
    if result.get('success'):
        return result['data']
    raise RuntimeError(result.get('error', 'Unknown error'))


def select(css_selector, url_filter=None, timeout=DEFAULT_TIMEOUT):
    """Return list of matching elements [{html, text, href, src}]."""
    result = _send_request(
        _build_msg('selector', selector=css_selector, url_filter=url_filter), timeout
    )
    if result.get('success'):
        return result['data']
    raise RuntimeError(result.get('error', 'Unknown error'))


def evaluate(js_expression, url_filter=None, timeout=DEFAULT_TIMEOUT):
    """Evaluate a JS expression in page context and return the result."""
    result = _send_request(
        _build_msg('evaluate', script=js_expression, url_filter=url_filter), timeout
    )
    if result.get('success'):
        return result['data']
    raise RuntimeError(result.get('error', 'Unknown error'))


def check_server():
    """Returns True if the bridge server is reachable."""
    try:
        s = socket.create_connection(('localhost', PORT), timeout=2)
        s.close()
        return True
    except OSError:
        return False


if __name__ == '__main__':
    # Quick test
    print(f'Server reachable: {check_server()}')
    if check_server():
        print('Scraping active tab...')
        r = scrape()
        if r.get('success'):
            print(f"Tab: {r['tab_title']}")
            print(f"URL: {r['tab_url']}")
            print(f"Text preview: {str(r['data'])[:500]}")
        else:
            print(f"Error: {r.get('error')}")

